contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);
        require(c.blacklist(address(this)) == false);
        uint256 beforeDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 beforeRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 beforeValue = c.value(); if (__ESBMC_reverted()) return;
        require(beforeRemaining >= beforeValue);
        uint256 beforeBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 expected = beforeValue;
        c.getTokens{value: amount}(); if (__ESBMC_reverted()) return;
        assert(c.balanceOf(address(this)) == beforeBalance + expected && c.totalDistributed() == beforeDistributed + expected && c.totalRemaining() == beforeRemaining - expected);
    }

    receive() external payable {}
}

