pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        vm.assume(c.blacklist(address(this)) == false);
        uint256 beforeDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeDistributed = __r; } catch { return; }
        uint256 beforeRemaining;
        try c.totalRemaining() returns (uint256 __r) { beforeRemaining = __r; } catch { return; }
        uint256 beforeValue;
        try c.value() returns (uint256 __r) { beforeValue = __r; } catch { return; }
        vm.assume(beforeRemaining >= beforeValue);
        uint256 beforeBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 expected = beforeValue;
        try c.getTokens{value: amount}() {} catch { return; }
        assertTrue(c.balanceOf(address(this)) == beforeBalance + expected && c.totalDistributed() == beforeDistributed + expected && c.totalRemaining() == beforeRemaining - expected);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
